// One probe per (product, query). Zero personal-brand queries by design —
// this measures PRODUCT visibility in AI answers.
const probes = [
  { venture: 'mm_ctrl',   product: 'CTRL',   query: 'best AI news decision tools for executives 2026' },
  { venture: 'mm_ctrl',   product: 'CTRL',   query: 'AI tool to cut through AI news noise' },
  { venture: 'legibility', product: 'Legibility', query: 'typed product data API for AI agents MCP' },
  { venture: 'legibility', product: 'Legibility', query: 'best MCP servers for product data' },
  { venture: 'fractionl_pulse', product: 'Fractionl', query: 'fractional executive tools platforms 2026' },
  { venture: 'full_time', product: 'Full Time', query: 'AI football recap podcast predictions' },
];
return probes.map(p => ({ json: p }));

// Deterministic string check — no LLM judging an LLM (false-positive guard).
const probes = $('Product query matrix').all().map(i => i.json);
const answers = $('Ask Perplexity').all();
const out = [];
answers.forEach((a, idx) => {
  const p = probes[idx] || {};
  const text = String(a.json?.choices?.[0]?.message?.content || '');
  const cited = text.toLowerCase().includes(String(p.product || '').toLowerCase());
  out.push({ json: {
    signal_type: 'geo-citation',
    venture: p.venture,
    description: `GEO probe: "${p.query}" — ${p.product} ${cited ? 'IS cited' : 'not cited'}`,
    summary: text.slice(0, 400),
    signal_score: cited ? 8 : 2,
    status: 'new',
    raw_data: { cited, surface: 'perplexity_sonar_pro', query: p.query, product: p.product },
  }});
});
return out;
